const editions={forest:{name:'Forest',x:70},burgundy:{name:'Burgundy',x:452},black:{name:'Black',x:837}};function renderEdition(){const slug=new URLSearchParams(location.search).get('color');const v=editions[slug]||editions.forest;const photo=document.querySelector('.edition-photo-stage svg');photo.setAttribute('viewBox',v.x+' 145 365 595');photo.querySelector('clipPath rect').setAttribute('x',v.x);photo.setAttribute('aria-label','Matterhorn Edition mouse in '+v.name);document.querySelector('#edition-color-name').textContent=v.name;document.title='Matterhorn Mouse / '+v.name+' — formkey';document.querySelectorAll('[data-edition-color]').forEach(a=>a.setAttribute('aria-current',String(editions[a.dataset.editionColor]===v)));document.querySelector('#edition-status').textContent='';}document.querySelectorAll('[data-edition-color]').forEach(a=>a.addEventListener('click',e=>{if(e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();history.pushState(null,'',a.href);renderEdition();}));addEventListener('popstate',renderEdition);document.querySelector('#share-edition').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);document.querySelector('#edition-status').textContent='Color link copied.';}catch{document.querySelector('#edition-status').textContent='Copy this link: '+location.href;}});renderEdition();